// <svg> for a brand mark (filled, 24x24 grid). color defaults to the brand's own hex.
export const brand = (k: string, size = 20, color?: string) => {
  const b = BRAND[k]!;
  return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="${color ?? b.hex}" aria-label="${b.title}" role="img"><path d="${b.path}"/></svg>`;
};
// <svg> for a Lucide line icon; inherits currentColor.
export const line = (k: string, size = 18) =>
  `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${LINE[k]}</svg>`;

