// Any mark by key: multi-color RAW first, then single-path BRAND.
export const logo = (k: string, size = 20, color?: string) =>
  RAW[k] ? RAW[k]!.svg.replace("<svg data-size ", `<svg width="${size}" height="${size}" role="img" aria-label="${RAW[k]!.title}" `) : brand(k, size, color);

